from fastapi.encoders import jsonable_encoder

result = jsonable_encoder({'keep': 1, 'drop': 2}, include={'keep'})
assert result == {'keep': 1}

from datetime import datetime

from fastapi.encoders import jsonable_encoder
from pydantic import BaseModel

class Model(BaseModel):
    value: datetime

    class Config:
        json_encoders = {}

model = Model(value=datetime(2020, 1, 1))
jsonable_encoder(model, custom_encoder={datetime: lambda value: 'custom'})
assert jsonable_encoder(model) == {'value': '2020-01-01T00:00:00'}
